const item = $input.first().json;
const body = item.body || {};
const headers = item.headers || {};
const received = headers['x-kredo-signature'] || headers['X-KREDO-Signature'] || '';
const expected = 'sha256=' + (item.computedSignature || '');
if (!received || received !== expected) throw new Error('Signature HMAC invalide');
for (const field of ['runId','workflowId','workspaceId','userId','input','callbackUrl']) {
  if (!body[field]) throw new Error('Champ requis manquant : ' + field);
}
if (body.workflowId !== 'intel-021-monthly-watch-analysis') throw new Error('workflowId invalide');
const input = body.input;

if (input.schemaVersion === 1) {
  for (const field of ['periodStart','periodEnd','digestIds','articleIds','requestedAt','triggerMode']) {
    if (input[field] === undefined) throw new Error('Champ input manquant : ' + field);
  }
  if (!Array.isArray(input.digestIds) || !Array.isArray(input.articleIds) || input.articleIds.length === 0) {
    throw new Error('digestIds/articleIds invalides');
  }
  if (!['manual','scheduled'].includes(input.triggerMode)) throw new Error('triggerMode invalide');
  return [{ json: { schemaVersion: 1, runId: body.runId, workspaceId: body.workspaceId, userId: body.userId, callbackUrl: body.callbackUrl, input } }];
} else if (input.schemaVersion === 2) {
  if (input.triggerMode !== 'manual_custom') throw new Error('triggerMode invalide pour V2');
  if (typeof input.intention !== 'string' || !input.intention.trim()) throw new Error('intention manquante ou vide');
  if (typeof input.requestedAt !== 'string' || !input.requestedAt.trim()) throw new Error('requestedAt manquant ou vide');
  if (!Array.isArray(input.refs) || input.refs.length === 0) throw new Error('refs doit être un tableau non vide');
  if (typeof input.stats !== 'object' || input.stats === null) throw new Error('stats requis');

  const allowedKinds = new Set(['veille_digest', 'veille_article', 'account_signal', 'intelligence_document']);
  for (const ref of input.refs) {
    if (!ref || typeof ref !== 'object' || !allowedKinds.has(ref.kind) || typeof ref.id !== 'string' || !ref.id.trim()) {
      throw new Error('Référence invalide dans refs');
    }
    if (ref.kind === 'veille_digest' && ref.articleIds !== undefined) {
      if (!Array.isArray(ref.articleIds) || ref.articleIds.length === 0 || ref.articleIds.some(id => typeof id !== 'string' || !id.trim())) {
        throw new Error('articleIds de digest invalides');
      }
    }
  }
  return [{ json: { schemaVersion: 2, runId: body.runId, workspaceId: body.workspaceId, userId: body.userId, callbackUrl: body.callbackUrl, input } }];
} else {
  throw new Error('schemaVersion invalide : ' + input.schemaVersion);
}

const item = $input.first().json;
if (item.schemaVersion === 2) {
  return [ [], [{ json: item }] ];
}
return [ [{ json: item }], [] ];

const base = $('Validate Input').item.json;
const digestsRaw = $('Load Digests').all().map(i => i.json);
const articlesRaw = $('Load Articles').all().map(i => i.json);
const digests = digestsRaw.flatMap(v => Array.isArray(v) ? v : [v]).filter(v => v && v.id);
const articles = articlesRaw.flatMap(v => Array.isArray(v) ? v : [v]).filter(v => v && v.id);
if (articles.length === 0) throw new Error('Aucun article hydraté');
const allowedIds = new Set(base.input.articleIds);
if (articles.some(a => !allowedIds.has(a.id))) throw new Error('Article hors contrat');
const systemPrompt = `Tu produis une analyse stratégique mensuelle à partir des seuls articles fournis. Règles absolues : aucune recherche externe, aucun chiffre inventé, aucune conclusion sans articleIds justificatifs. La sortie est un JSON strict respectant exactement le schéma demandé. Les niveaux de confiance sont entre 0 et 1.`;
const schema = { schemaVersion: 1, period: { start: base.input.periodStart, end: base.input.periodEnd, label: 'libellé français du mois' }, executiveSummary: 'string', majorTrends: [{ title:'string', synthesis:'string', articleIds:['uuid'], sectors:['string'], confidence:0.8 }], weakSignals:[{title:'string',synthesis:'string',articleIds:['uuid']}], regulatoryDevelopments:[{title:'string',impact:'string',articleIds:['uuid']}], commercialOpportunities:[{title:'string',rationale:'string',recommendedAction:'string',practices:['string'],articleIds:['uuid']}], risksAndWatchpoints:[{title:'string',explanation:'string',articleIds:['uuid']}], priorityActions:[{title:'string',action:'string',horizon:'immediate|30_days|quarter'}], coverage:{digestsCount:digests.length,articlesCount:articles.length,sourcesCount:new Set(articles.map(a=>a.source_name).filter(Boolean)).size} };
return [{ json: { ...base, digests, articles, systemPrompt, userPrompt: 'SCHÉMA ATTENDU\n' + JSON.stringify(schema) + '\n\nARTICLES — SOURCE UNIQUE\n' + JSON.stringify(articles) } }];

const response = $input.first().json;
const base = $('Assemble Prompt').item.json;
const text = (response.content || []).find(b => b.type === 'text')?.text || '';
let output;
try { output = JSON.parse(text.replace(/```json\n?/g,'').replace(/```\n?/g,'').trim()); } catch { throw new Error('Réponse LLM non JSON'); }
const arrays = ['majorTrends','weakSignals','regulatoryDevelopments','commercialOpportunities','risksAndWatchpoints','priorityActions'];
if (output.schemaVersion !== 1 || !output.period || !output.executiveSummary || arrays.some(k => !Array.isArray(output[k])) || !output.coverage) throw new Error('Sortie structurée invalide');
const allowed = new Set(base.articles.map(a => a.id));
for (const key of arrays.slice(0,5)) for (const item of output[key]) { if (!Array.isArray(item.articleIds) || item.articleIds.length === 0 || item.articleIds.some(id => !allowed.has(id))) throw new Error('Traçabilité articleIds invalide dans ' + key); }
output.period = { start: base.input.periodStart, end: base.input.periodEnd, label: output.period.label };
output.coverage = { digestsCount: base.digests.length, articlesCount: base.articles.length, sourcesCount: new Set(base.articles.map(a => a.source_name).filter(Boolean)).size };
const qaFlags = [{check:'article_traceability',passed:true},{check:'coverage_from_source_rows',passed:true},{check:'no_external_collection',passed:true}];
return [{ json: { ...base, output, qaFlags, llmUsage: response.usage || {}, model: response.model || 'claude-sonnet-5' } }];

const d = $input.first().json;
const o = d.output;
const lines = ['# Analyse stratégique de la veille — ' + o.period.label, o.executiveSummary, '', '## Tendances majeures', ...o.majorTrends.map(x => '- ' + x.title + ' — ' + x.synthesis), '', '## Signaux faibles', ...o.weakSignals.map(x => '- ' + x.title + ' — ' + x.synthesis), '', '## Opportunités commerciales', ...o.commercialOpportunities.map(x => '- ' + x.title + ' — ' + x.recommendedAction), '', '## Risques et points de veille', ...o.risksAndWatchpoints.map(x => '- ' + x.title + ' — ' + x.explanation), '', '## Actions prioritaires', ...o.priorityActions.map(x => '- ' + x.title + ' — ' + x.action)];
const sourceRefs = d.articles.map(a => ({ entityType:'veille_article', entityId:a.id, label:a.titre_fr, sourceName:a.source_name }));
const callback = { n8nExecutionId:$execution.id, n8nWorkflowId:$workflow.id, runId:d.runId, phase:1, resultType:'strategic_watch_analysis', status:'succeeded', contentJson:{ ...o, dataCutoffAt:d.input.periodEnd + 'T23:59:59.999Z' }, contentText:lines.join('\n'), title:'Analyse stratégique de la veille — ' + o.period.label, modelProvider:'anthropic', modelUsed:d.model, tokensInput:d.llmUsage.input_tokens || null, tokensOutput:d.llmUsage.output_tokens || null, contextSnapshot:d.input, sourceRefs, qaFlags:d.qaFlags };
return [{ json:{ callbackUrl:d.callbackUrl, rawBody:JSON.stringify(callback) } }];

const base = $('Route Schema Version').item.json;
const workspaceId = base.workspaceId;
const refs = base.input.refs || [];

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || 'https://jvzgmhvwirsbdkjpmvla.supabase.co';
const supabaseKey = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.SUPABASE_ANON_KEY || '';

async function querySupabase(table, queryStr) {
  const url = `${supabaseUrl}/rest/v1/${table}?${queryStr}`;
  if (typeof this !== 'undefined' && this.helpers && typeof this.helpers.httpRequest === 'function') {
    return await this.helpers.httpRequest({
      method: 'GET',
      url,
      headers: {
        'apikey': supabaseKey,
        'Authorization': `Bearer ${supabaseKey}`,
        'Accept': 'application/json'
      },
      json: true
    });
  } else if (typeof fetch === 'function') {
    const res = await fetch(url, {
      headers: {
        'apikey': supabaseKey,
        'Authorization': `Bearer ${supabaseKey}`,
        'Accept': 'application/json'
      }
    });
    if (!res.ok) throw new Error(`HTTP ${res.status} on ${table}`);
    return await res.json();
  } else {
    throw new Error('Aucun client HTTP disponible pour querySupabase');
  }
}

const hydratedItems = [];

for (const ref of refs) {
  if (ref.kind === 'veille_digest') {
    let query;
    if (Array.isArray(ref.articleIds) && ref.articleIds.length > 0) {
      const idsStr = ref.articleIds.join(',');
      query = `select=id,digest_id,published_at,selection_rank,source_name,titre_fr,resume,categorie,secteur_principal,analyse_kredo,action_commerciale,tags&id=in.(${idsStr})&workspace_id=eq.${workspaceId}`;
    } else {
      query = `select=id,digest_id,published_at,selection_rank,source_name,titre_fr,resume,categorie,secteur_principal,analyse_kredo,action_commerciale,tags&digest_id=eq.${ref.id}&workspace_id=eq.${workspaceId}`;
    }
    const rows = await querySupabase('veille_articles', query);
    const list = Array.isArray(rows) ? rows : [rows];
    if (list.length === 0 || (Array.isArray(ref.articleIds) && list.length < ref.articleIds.length)) {
      throw new Error('Référence non hydratable : veille_digest ' + ref.id);
    }
    for (const item of list) {
      if (!item || !item.id) continue;
      hydratedItems.push({
        kind: 'veille_article',
        id: item.id,
        title: item.titre_fr || 'Article de veille',
        provenance: item.source_name || 'Veille KREDO',
        content: JSON.stringify({
          titre: item.titre_fr,
          resume: item.resume,
          analyse_kredo: item.analyse_kredo,
          action_commerciale: item.action_commerciale,
          categorie: item.categorie,
          secteur: item.secteur_principal,
          published_at: item.published_at
        })
      });
    }
  } else if (ref.kind === 'veille_article') {
    const query = `select=id,digest_id,published_at,selection_rank,source_name,titre_fr,resume,categorie,secteur_principal,analyse_kredo,action_commerciale,tags&id=eq.${ref.id}&workspace_id=eq.${workspaceId}`;
    const rows = await querySupabase('veille_articles', query);
    const list = Array.isArray(rows) ? rows : [rows];
    const item = list[0];
    if (!item || !item.id) throw new Error('Référence non hydratable : veille_article ' + ref.id);
    hydratedItems.push({
      kind: 'veille_article',
      id: item.id,
      title: item.titre_fr || 'Article de veille',
      provenance: item.source_name || 'Veille KREDO',
      content: JSON.stringify({
        titre: item.titre_fr,
        resume: item.resume,
        analyse_kredo: item.analyse_kredo,
        action_commerciale: item.action_commerciale,
        categorie: item.categorie,
        secteur: item.secteur_principal,
        published_at: item.published_at
      })
    });
  } else if (ref.kind === 'account_signal') {
    const query = `select=id,company_id,title,summary,category,detected_at,recommended_action&id=eq.${ref.id}&workspace_id=eq.${workspaceId}`;
    const rows = await querySupabase('account_signals', query);
    const list = Array.isArray(rows) ? rows : [rows];
    const item = list[0];
    if (!item || !item.id) throw new Error('Référence non hydratable : account_signal ' + ref.id);
    hydratedItems.push({
      kind: 'account_signal',
      id: item.id,
      title: item.title || 'Signal compte',
      provenance: 'Signal compte KREDO',
      content: JSON.stringify({
        title: item.title,
        summary: item.summary,
        category: item.category,
        detected_at: item.detected_at,
        recommended_action: item.recommended_action
      })
    });
  } else if (ref.kind === 'intelligence_document') {
    const query = `select=id,title,document_type,current_content_text,current_content_json&id=eq.${ref.id}&workspace_id=eq.${workspaceId}`;
    const rows = await querySupabase('intelligence_documents', query);
    const list = Array.isArray(rows) ? rows : [rows];
    const item = list[0];
    if (!item || !item.id) throw new Error('Référence non hydratable : intelligence_document ' + ref.id);
    hydratedItems.push({
      kind: 'intelligence_document',
      id: item.id,
      title: item.title || 'Document KREDO',
      provenance: 'Bibliothèque documentaire KREDO',
      content: item.current_content_text || JSON.stringify(item.current_content_json || {})
    });
  }
}

const dedupedMap = new Map();
for (const item of hydratedItems) {
  const key = `${item.kind}:${item.id}`;
  if (!dedupedMap.has(key)) {
    dedupedMap.set(key, item);
  }
}

const hydratedCorpus = Array.from(dedupedMap.values());
if (hydratedCorpus.length === 0) throw new Error('Corpus V2 vide');

return [{ json: { ...base, hydratedCorpus } }];

const base = $('Hydrate Corpus V2').item.json;
const intention = base.input.intention;
const corpus = base.hydratedCorpus || [];

const systemPrompt = `Tu produis une analyse stratégique sur mesure à partir du corpus fourni et de l'intention utilisateur.
Règles absolues :
1. N'effectue aucune recherche externe.
2. Utilise uniquement le corpus fourni. Aucun fait inventé.
3. Chaque conclusion (tendance, signal faible, évolution réglementaire, opportunité commerciale, risque, action prioritaire) DOIT citer au moins une preuve valide via "evidenceRefs".
4. Chaque "evidenceRef" doit être un objet contenant uniquement : {"kind": "...", "id": "..."}.
   Kinds autorisés : "veille_article", "account_signal", "intelligence_document".
   Seuls les IDs présents dans le corpus sont autorisés.
5. La sortie doit être un JSON strict respectant exactement le schéma demandé.`;

const schemaExpected = {
  schemaVersion: 2,
  analysisKind: "manual_custom",
  title: "Titre explicite de l'analyse synthétisant l'angle",
  executiveSummary: "Synthèse exécutive guidée par l'intention utilisateur",
  majorTrends: [{
    title: "string",
    synthesis: "string",
    sectors: ["string"],
    confidence: 0.85,
    evidenceRefs: [{ kind: "veille_article", id: "uuid" }]
  }],
  weakSignals: [{
    title: "string",
    synthesis: "string",
    evidenceRefs: [{ kind: "account_signal", id: "uuid" }]
  }],
  regulatoryDevelopments: [{
    title: "string",
    impact: "string",
    evidenceRefs: [{ kind: "intelligence_document", id: "uuid" }]
  }],
  commercialOpportunities: [{
    title: "string",
    rationale: "string",
    recommendedAction: "string",
    practices: ["string"],
    evidenceRefs: [{ kind: "veille_article", id: "uuid" }]
  }],
  risksAndWatchpoints: [{
    title: "string",
    explanation: "string",
    evidenceRefs: [{ kind: "account_signal", id: "uuid" }]
  }],
  priorityActions: [{
    title: "string",
    action: "string",
    horizon: "immediate",
    evidenceRefs: [{ kind: "veille_article", id: "uuid" }]
  }]
};

const userPrompt = `INTENTION UTILISATEUR :\n${intention}\n\nSCHÉMA JSON ATTENDU :\n${JSON.stringify(schemaExpected, null, 2)}\n\nCORPUS DE SOURCES FOURNI :\n${JSON.stringify(corpus, null, 2)}`;

return [{ json: { ...base, systemPrompt, userPrompt } }];

const response = $input.first().json;
const base = $('Assemble Prompt V2').item.json;
const text = (response.content || []).find(b => b.type === 'text')?.text || '';

let output;
try {
  output = JSON.parse(text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim());
} catch {
  throw new Error('Réponse LLM non JSON');
}

const sectionsWithEvidence = [
  'majorTrends',
  'weakSignals',
  'regulatoryDevelopments',
  'commercialOpportunities',
  'risksAndWatchpoints',
  'priorityActions'
];

if (
  output.schemaVersion !== 2 ||
  output.analysisKind !== 'manual_custom' ||
  !output.title ||
  !output.executiveSummary ||
  sectionsWithEvidence.some(k => !Array.isArray(output[k]))
) {
  throw new Error('Sortie structurée V2 invalide');
}

const corpusMap = new Map();
for (const item of (base.hydratedCorpus || [])) {
  corpusMap.set(`${item.kind}:${item.id}`, item);
}

for (const secKey of sectionsWithEvidence) {
  const items = output[secKey];
  for (const item of items) {
    if (!Array.isArray(item.evidenceRefs) || item.evidenceRefs.length === 0) {
      throw new Error(`evidenceRefs manquants ou vides dans ${secKey}`);
    }
    const validatedRefs = [];
    for (const ref of item.evidenceRefs) {
      if (!ref || typeof ref !== 'object' || !ref.kind || !ref.id) {
        throw new Error(`evidenceRef malformé dans ${secKey}`);
      }
      const key = `${ref.kind}:${ref.id}`;
      const canonical = corpusMap.get(key);
      if (!canonical) {
        throw new Error(`evidenceRef inconnu ou hors corpus dans ${secKey} : ${key}`);
      }
      validatedRefs.push({
        kind: ref.kind,
        id: ref.id,
        title: canonical.title,
        provenance: canonical.provenance
      });
    }
    item.evidenceRefs = validatedRefs;
  }
}

const articlesCount = base.hydratedCorpus.filter(i => i.kind === 'veille_article').length;
const signalsCount = base.hydratedCorpus.filter(i => i.kind === 'account_signal').length;
const documentsCount = base.hydratedCorpus.filter(i => i.kind === 'intelligence_document').length;

output.coverage = {
  sourceGroups: base.input.stats?.sourceGroups || base.input.sources?.length || 0,
  resolvedRefs: base.input.stats?.resolvedRefs || base.input.refs?.length || 0,
  articlesCount,
  signalsCount,
  documentsCount,
  totalItems: base.hydratedCorpus.length
};

const qaFlags = [
  { check: 'evidence_traceability', passed: true },
  { check: 'resolved_refs_only', passed: true },
  { check: 'no_external_collection', passed: true },
  { check: 'coverage_from_hydrated_corpus', passed: true }
];

return [{
  json: {
    ...base,
    output,
    qaFlags,
    llmUsage: response.usage || {},
    model: response.model || 'claude-sonnet-5'
  }
}];

const failure = $input.first().json;
const webhook = $('Webhook — Monthly Watch').item.json.body || {};
const validated = (() => {
  try { return $('Validate Input').item.json; } catch { return null; }
})();
const runId = validated?.runId || webhook.runId;
const callbackUrl = validated?.callbackUrl || webhook.callbackUrl;
if (!runId || !callbackUrl) throw new Error('Impossible de notifier l’échec : runId/callbackUrl absents');
const message = failure.error?.message || failure.message || failure.errorMessage || 'Échec du workflow INTEL-021';
const callback = {
  n8nExecutionId: typeof $execution !== 'undefined' ? $execution.id : 'test-exec-id',
  n8nWorkflowId: typeof $workflow !== 'undefined' ? $workflow.id : 'intel-021-monthly-watch-analysis',
  runId,
  phase: 1,
  resultType: 'strategic_watch_analysis',
  status: 'failed',
  contentJson: { error: message },
  contentText: '',
  title: 'Analyse stratégique de la veille — échec',
  errorMessage: message
};
return [{ json: { callbackUrl, rawBody: JSON.stringify(callback) } }];
